function boardQuarterRows(){const grouped=new Map();for(const offset of ids()){const d=periodDate(offset),key=d.year+' Q'+(Math.floor(d.month/3)+1);if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(offset);}return [...grouped].map(([name,ms])=>[name+(ms.length<3?' (selected months)':''),money(rv(31,ms)),money(rv(67,ms)),pct(percent(rv(46,ms),rv(31,ms))),pct(percent(rv(51,ms),rv(31,ms))),pct(percent(rv(31,ms),rv(31,ms,'Budget')))]);}
function boardView(){const controls=comparisonControls(),m=performanceMeasures(),cash=cashMetrics(),old=state.driverComparison;state.driverComparison=reviewComparison==='budget'?'budget':'year:'+reviewComparison;const bridge=profitBridge();state.driverComparison=old;const adverse=bridge.unavailable?[]:bridge.drivers.filter(d=>d.value<0).sort((a,b)=>a.value-b.value).slice(0,3),gap=sub(m.profit,m.b(67)),defs=economicsDefinitions().map(p=>({...p,metrics:economicsMeasure(p)})),known=defs.filter(p=>p.metrics.spread!==null),negative=known.filter(p=>p.metrics.spread<0),netBreak=breakModel(),checks=reconciliationRows().filter(([,a,b])=>a!==null&&b!==null&&Math.abs(a-b)>.01),headline=m.profit===null?'Complete the evidence before assessing performance.':m.profit<0?'Sales are not yet translating into net profit.':'The business is reporting a net profit.',marginFirst=ids()[0],marginLast=ids().at(-1),first=percent(rv(67,[marginFirst]),rv(31,[marginFirst])),last=percent(rv(67,[marginLast]),rv(31,[marginLast]));return controls+`<section class="panel board-summary"><div class="eyebrow">BOARD REVIEW · ${esc(period())}</div><h2>${headline}</h2><p>${gap===null?'Comparable profit data are incomplete.':`Net profit is ${money(Math.abs(gap))} ${unit()} ${gap<0?'below':'above'} ${m.c.label}.`} ${m.operating===null?'':m.operating<0?'Operations report a loss before finance and tax.':'Operations report a profit before finance and tax.'}</p><button class="action" data-view="drivers">Explain profit changes</button> <button class="action" id="boardPrint">Print review</button></section><div class="cards">${card('Net profit / loss',money(m.profit),unit(),67)}${card('Net profit margin',pct(m.margin),'Comparison '+pct(percent(m.b(67),m.b(31))))}${card('Operating profit',money(m.operating),'Before finance and tax · '+unit(),51)}${card('Operating cash flow',money(cash.ocf),'Formal cash-flow statement · '+unit())}${card('Sales against comparison',pct(m.salesAchievement),m.c.label)}${card('Interest expense cover',times(m.cover),'Operating profit / reported interest expense')}${card('Reported capacity used',pct(m.capacity),'Production / source capacity')}${card('Period ROCE',pct(m.roce),'Operating profit / average capital; not annualized')}</div><div class="grid">`+
panel('1. Is profit improving sustainably?','Selected-period profitability',`<p>${first===null||last===null?'Comparable monthly profit margins are incomplete.':`${periodMonthLabel(marginLast)} net margin is ${pct(last)}. ${ids().length>1?`Change from ${periodMonthLabel(marginFirst)}: ${num(last-first,1)} percentage points.`:''}`}</p><button class="action" data-view="overview">See monthly performance →</button>`)+
panel('2. Is cash coming from the business?','Formal operating cash and capital payments',`<p>Operating cash: ${money(cash.ocf)} ${unit()}. PPE/CWIP cash flows: ${money(cash.capex)} ${unit()}. Cash after these payments: ${money(cash.afterCapex)} ${unit()}.</p><button class="action" data-view="cash">Review cash sources →</button>`)+
panel('3. What will restore or strengthen profitability?','Planning estimates using the current source cost pattern',`<p>Revenue for estimated net break-even: ${money(netBreak.be)} ${unit()}. Validate cost behaviour and sales mix before approving targets.</p><button class="action" data-view="breakeven">Open break-even planner →</button>`)+
panel('Largest adverse profit drivers','Against '+m.c.label+' · '+unit()+'. Observed bridge contributions; not independently proven causes.',adverse.length?table(['Driver','Profit impact'],adverse.map(d=>[`<button data-view="drivers">${esc(d.name)}</button>`,money(d.value)])):empty(bridge.unavailable?'Comparable driver inputs are incomplete':'No adverse comparable driver identified'))+
panel('Board questions for this review','Suggested discussion leads; not assigned tasks.',table(['Question','Suggested lead'],[['Which products show negative indicative spreads, and what pricing or costing action is required?','Sales + COO + Finance'],['Which inventory valuation, rejection or purchase changes explain material cost movements?','Finance + Factory + QC'],['Which sales and cost targets close the profit gap?','COO + Sales + Finance'],['How much cash is sustainable operating generation versus funding or working-capital movement?','CFO / Finance']]))+'</div>'+
panel('Quarterly performance','Selected months grouped by calendar quarter. Partial quarters are labelled; missing inputs remain blank.',table(['Quarter','Net sales','Net profit','Gross margin','Operating margin','Sales budget achieved'],boardQuarterRows()))+
`<div class="grid">`+panel('Return on capital: the two drivers','Capital employed = total assets − current liabilities. Average opening and closing balances; unavailable for non-contiguous selections.',table(['Measure','Selected period'],[['Operating margin on net sales',pct(percent(m.operating,m.sales))],['Net sales / average capital employed',times(m.turnover)],['Period ROCE',pct(m.roce)],['Average capital employed',money(m.averageCapital)+' '+unit()]]))+
panel('Product pricing and cost signals','Supplied pricing schedules matched to product data where labels agree. Indicative spread is not net product profit.',table(['Measure','Selected period'],[['Products with comparable rates',known.length],['Products with negative indicative spread',known.length?negative.length:'—'],['Negative-spread products',negative.map(p=>esc(p.name)).join(', ')||(known.length?'None':'—')]]))+panel('Liquidity and funding position','Closing balances; short-term investment liquidity is not established.',table(['Measure','Selected period'],[['Net working capital',money(cash.nwc)+' '+unit()],['Current ratio',times(cash.currentRatio)],['Current ratio excluding investments',times(cash.exInvestmentRatio)],['Net bank and lease debt',money(cash.netDebt)+' '+unit()]]))+panel('Source reconciliation signals','Includes available balance sheet, cash-flow and equity checks. Differences are not adjusted.',checks.length?table(['Check','Difference · '+unit()],checks.map(([name,a,b])=>[`<button data-view="reconcile">${esc(name)}</button>`,money(a-b)])):empty('No difference found among available checks','Unavailable checks are not treated as reconciled.'))+'</div>'+
panel('Complete the evidence for the next review','Additional inputs to improve decisions.',table(['Missing input','Decision supported'],[['Reconciled product cost allocations and SKU contribution','Validate pricing and profitable growth'],['Customer sales, credit terms and receivable aging','Prioritize collections and assess credit risk'],['Rejection, yield, downtime and energy per production tonne','Separate physical efficiency from accounting movements'],['Approved future targets with initiative owners and due dates','Assess recovery plans against approved commitments']]))+`<p class="source">Signals are based on source losses, comparison gaps and coverage ratios, not external industry benchmarks. Period ROCE is not annualized and includes company investments within capital employed. Historical source labels are preserved.</p>`;}
const performanceBind=bind;bind=function(){performanceBind();if(!['overview','board'].includes(state.view))return;if($('reviewComparison'))$('reviewComparison').onchange=e=>{reviewComparison=e.target.value;render();};if($('boardPrint'))$('boardPrint').onclick=()=>window.print();$('export').onclick=reviewExport;$('export').textContent='Export current view CSV';};
